// Build Email - Get newsletter (Data Table) reste intact
const CFG = {
  TRACK_BASE: 'https://n8n.exemple.invalid/webhook/email-click',
  UNSUB_BASE: 'https://n8n.exemple.invalid/webhook/unsubscribe',
  RDV_URL: 'https://www.nouvelleecole.fr/rdv-commercials#drone',
  PROGRAMME_URL: 'https://www.nouvelleecole.fr/formation-telepilotage-de-drone',
};
const YT = {
  Newsletter_1: 'https://www.youtube.com/watch?v=QKgT3bSc9Hs',
  Newsletter_2: 'https://www.youtube.com/watch?v=P-OrhuGg214',
  Newsletter_3: 'https://www.youtube.com/watch?v=GnzzT2UO10Q',
  Newsletter_4: 'https://www.youtube.com/watch?v=vZs0_T8to6U',
  Newsletter_5: 'https://www.youtube.com/watch?v=4gE6_xH83vI',
  Newsletter_6: 'https://www.youtube.com/watch?v=PgJ9Z3wWtFA',
};
const out = [];
for (const item of $input.all()) {
  const row = item.json;
  const lead = $('Airtable Trigger').item.json;
  const f = lead.fields || {};
  if (f['Stop call']) continue;
  const col = (f['Newsletter Formule'] || '').trim().replace(/\s+/g, '_');
  if (!col) throw new Error('Newsletter Formule vide (lead ' + lead.id + ')');
  const htmlRaw = row[col];
  const subject = (row['Titre_' + col] || '').trim();
  if (!htmlRaw) throw new Error('Colonne ' + col + ' vide dans la Data Table (formation ' + (f['Demande Formation'] || '?') + ')');
  const email = f['Email'] || '';
  const eEmail = encodeURIComponent(email);
  const unsub = CFG.UNSUB_BASE + '?lead_id=' + encodeURIComponent(lead.id) + '&amp;email=' + eEmail;
  let html = htmlRaw
    .replaceAll('{{track_base}}', CFG.TRACK_BASE)
    .replaceAll('{{lead_id}}', encodeURIComponent(lead.id))
    .replaceAll('{{email}}', eEmail)
    .replaceAll('{{prenom}}', f['Prénom'] || '')
    .replaceAll('{{prenom_commercial}}<br/>', '')
    .replaceAll('{{prenom_commercial}}', '')
    .replaceAll('{{UNSUBSCRIBE_URL}}', unsub);
  const ytUrl = YT[col] || CFG.PROGRAMME_URL;
  html = html
    .split('&amp;target=youtube').join('&amp;target=youtube&amp;url=' + encodeURIComponent(ytUrl))
    .split('&amp;target=rdv').join('&amp;target=rdv&amp;url=' + encodeURIComponent(CFG.RDV_URL))
    .split('&amp;target=programme').join('&amp;target=programme&amp;url=' + encodeURIComponent(CFG.PROGRAMME_URL));
  out.push({ json: { to: email, subject: subject || '', html, email_id: col, lead_id: lead.id } });
}
return out;
